 45	func walkFolder(ctx context.Context, currentFolder string, results chan<- dirStats) error {
 46		select {
 47		case <-ctx.Done():
 48			return nil
 49		default:
 50		}
 51	
 52		children, stats, err := loadDir(ctx, currentFolder)
 53		if err != nil {
 54			return err
 55		}
 56		for _, child := range children {
 57			if err := walkFolder(ctx, child, results); err != nil {
 58				return err
 59			}
 60		}
 61	
 62		dir := filepath.Clean(currentFolder)
 63		log.Trace(ctx, "Found directory", "dir", dir, "audioCount", stats.AudioFilesCount,
 64			"images", stats.Images, "hasPlaylist", stats.HasPlaylist)
 65		stats.Path = dir
 66		results <- *stats
 67	
 68		return nil
 69	}
