 71	func loadDir(ctx context.Context, dirPath string) ([]string, *dirStats, error) {
 72		var children []string
 73		stats := &dirStats{}
 74	
 75		dirInfo, err := os.Stat(dirPath)
 76		if err != nil {
 77			log.Error(ctx, "Error stating dir", "path", dirPath, err)
 78			return nil, nil, err
 79		}
 80		stats.ModTime = dirInfo.ModTime()
 81	
 82		dir, err := os.Open(dirPath)
 83		if err != nil {
 84			log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
 85			return children, stats, err
 86		}
 87		defer dir.Close()
 88		if !dirInfo.IsDir() {
 89			log.Error(ctx, "Not a directory", "path", dirPath)
 90			return children, stats, nil
 91		}
 92	
 93		for _, entry := range fullReadDir(ctx, dir) {
 94			isDir, err := isDirOrSymlinkToDir(dirPath, entry)
 95			// Skip invalid symlinks
 96			if err != nil {
 97				log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
 98				continue
 99			}
100			childPath := filepath.Join(dirPath, entry.Name())
101			if isDir && !isDirIgnored(dirPath, entry) {
102				readable, err := utils.IsDirReadable(childPath)
103				if readable {
104					children = append(children, childPath)
105				} else {
106					log.Warn(ctx, "Skipping unreadable directory", "path", childPath, err)
107				}
108			} else {
109				fileInfo, err := entry.Info()
110				if err != nil {
111					log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
112					return children, stats, err
113				}
114				if fileInfo.ModTime().After(stats.ModTime) {
115					stats.ModTime = fileInfo.ModTime()
116				}
117				switch {
118				case model.IsAudioFile(entry.Name()):
119					stats.AudioFilesCount++
120				case model.IsValidPlaylist(entry.Name()):
121					stats.HasPlaylist = true
122				case model.IsImageFile(entry.Name()):
123					stats.Images = append(stats.Images, entry.Name())
124					if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
125						stats.ImagesUpdatedAt = fileInfo.ModTime()
126					}
127				}
128			}
129		}
130		return children, stats, nil
131	}
