133	// fullReadDir reads all files in the folder, skipping the ones with errors.
134	// It also detects when it is "stuck" with an error in the same directory over and over.
135	// In this case, it stops and returns whatever it was able to read until it got stuck.
136	// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
137	func fullReadDir(ctx context.Context, dir *os.File) []os.DirEntry {
138		var allEntries []os.DirEntry
139		var prevErrStr = ""
140		for {
141			entries, err := dir.ReadDir(-1)
142			allEntries = append(allEntries, entries...)
143			if err == nil {
144				break
145			}
146			log.Warn(ctx, "Skipping DirEntry", err)
147			if prevErrStr == err.Error() {
148				log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
149				break
150			}
151			prevErrStr = err.Error()
152		}
153		sort.Slice(allEntries, func(i, j int) bool { return allEntries[i].Name() < allEntries[j].Name() })
154		return allEntries
155	}
