157	// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
158	// system directory, or a symbolic link to a directory. Note that if the dirEnt
159	// is not a directory but is a symbolic link, this method will resolve by
160	// sending a request to the operating system to follow the symbolic link.
161	// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
162	// efficiency for go 1.16 and beyond
163	func isDirOrSymlinkToDir(baseDir string, dirEnt os.DirEntry) (bool, error) {
164		if dirEnt.IsDir() {
165			return true, nil
166		}
167		if dirEnt.Type()&os.ModeSymlink == 0 {
168			return false, nil
169		}
170		// Does this symlink point to a directory?
171		fileInfo, err := os.Stat(filepath.Join(baseDir, dirEnt.Name()))
172		if err != nil {
173			return false, err
174		}
175		return fileInfo.IsDir(), nil
176	}
