178	// isDirIgnored returns true if the directory represented by dirEnt contains an
179	// `ignore` file (named after skipScanFile)
180	func isDirIgnored(baseDir string, dirEnt os.DirEntry) bool {
181		// allows Album folders for albums which eg start with ellipses
182		if strings.HasPrefix(dirEnt.Name(), ".") && !strings.HasPrefix(dirEnt.Name(), "..") {
183			return true
184		}
185		if runtime.GOOS == "windows" && dirEnt.Name() == "$Recycle.Bin" {
186			return true
187		}
188		_, err := os.Stat(filepath.Join(baseDir, dirEnt.Name(), consts.SkipScanFile))
189		return err == nil
190	}
